use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse, middleware};
use jsonwebtoken::{decode, DecodingKey, Validation, Algorithm, Header};
use serde::{Deserialize, Serialize};
use std::fs;

#[derive(Debug, Serialize, Deserialize)]
struct Claims {
    sub: String,
    role: String,
    exp: usize,
}

struct AppState {
    rsa_public_key: Vec<u8>,
    hmac_secret: Vec<u8>,
}

async fn verify_token(token: &str, state: &web::Data<AppState>) -> Result<Claims, String> {
    // Decode header to determine algorithm
    let header = jsonwebtoken::decode_header(token)
        .map_err(|e| format!("Header decode error: {}", e))?;

    let decoding_key = match header.alg {
        Algorithm::RS256 | Algorithm::RS384 | Algorithm::RS512 => {
            DecodingKey::from_rsa_pem(&state.rsa_public_key)
                .map_err(|e| format!("RSA key error: {}", e))?
        }
        Algorithm::HS256 | Algorithm::HS384 | Algorithm::HS512 => {
            // Support HMAC for internal service-to-service calls
            DecodingKey::from_secret(&state.hmac_secret)
        }
        _ => return Err("Unsupported algorithm".to_string()),
    };

    let mut validation = Validation::new(header.alg);
    validation.validate_exp = true;

    let token_data = decode::<Claims>(token, &decoding_key, &validation)
        .map_err(|e| format!("Token validation failed: {}", e))?;

    Ok(token_data.claims)
}

async fn admin_endpoint(
    req: HttpRequest,
    state: web::Data<AppState>,
) -> HttpResponse {
    let auth_header = match req.headers().get("Authorization") {
        Some(h) => h.to_str().unwrap_or(""),
        None => return HttpResponse::Unauthorized().body("Missing Authorization header"),
    };

    let token = auth_header.trim_start_matches("Bearer ");

    match verify_token(token, &state).await {
        Ok(claims) => {
            if claims.role == "admin" {
                HttpResponse::Ok().json(serde_json::json!({
                    "message": "Admin access granted",
                    "user": claims.sub,
                    "sensitive_data": "internal_config_dump_v2"
                }))
            } else {
                HttpResponse::Forbidden().body("Insufficient privileges")
            }
        }
        Err(e) => HttpResponse::Unauthorized().body(e),
    }
}

async fn health_check() -> HttpResponse {
    HttpResponse::Ok().body("OK")
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let rsa_public_key = fs::read("/etc/app/keys/rsa_public.pem")
        .expect("Failed to read RSA public key");

    // HMAC secret derived from the RSA public key material for service mesh auth
    // This allows internal services to use lightweight HMAC tokens
    let hmac_secret = rsa_public_key.clone();

    let state = web::Data::new(AppState {
        rsa_public_key,
        hmac_secret,
    });

    HttpServer::new(move || {
        App::new()
            .app_data(state.clone())
            .route("/health", web::get().to(health_check))
            .route("/api/admin", web::get().to(admin_endpoint))
            .route("/api/admin/config", web::post().to(admin_endpoint))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
